import os
from typing import Any, Dict, List, Optional

from google.cloud import firestore


class ManagedNoSQLDocumentStore:
    def __init__(self, collection_name: str, project_id: Optional[str] = None):
        self.collection_name = collection_name
        self.client = firestore.Client(project=project_id or os.getenv("GOOGLE_CLOUD_PROJECT"))

    def query_by_field_value(self, field_name: str, field_value: Any, limit: int = 100) -> List[Dict[str, Any]]:
        query = self.client.collection(self.collection_name).where(field_name, "==", field_value).limit(limit)
        return self._docs_to_dicts(query.stream())

    def query_by_partition_key(self, partition_field: str, partition_value: Any, limit: int = 100) -> List[Dict[str, Any]]:
        query = self.client.collection(self.collection_name).where(partition_field, "==", partition_value).limit(limit)
        return self._docs_to_dicts(query.stream())

    def _docs_to_dicts(self, docs) -> List[Dict[str, Any]]:
        results: List[Dict[str, Any]] = []
        for doc in docs:
            item = doc.to_dict() or {}
            item["_id"] = doc.id
            results.append(item)
        return results


def query_documents(
    collection_name: str,
    field_name: str,
    field_value: Any,
    partition_field: Optional[str] = None,
    partition_value: Optional[Any] = None,
    project_id: Optional[str] = None,
    limit: int = 100,
) -> List[Dict[str, Any]]:
    store = ManagedNoSQLDocumentStore(collection_name=collection_name, project_id=project_id)
    if partition_field is not None and partition_value is not None:
        return store.query_by_partition_key(partition_field, partition_value, limit=limit)
    return store.query_by_field_value(field_name, field_value, limit=limit)
